<template><AccountLayout bare><main class="po-page" :aria-busy="busy">
<header class="po-header"><div class="po-heading"><ReceiptText :size="30"/><div><h1>Bill Payment</h1><p>Vendor bill entries and allocations</p></div></div><div v-if="view==='list'" class="po-header-search"><Search/><input v-model="filters.search" placeholder="Search payment no., reference or vendor..."></div><div class="po-actions"><button v-if="view==='list'" class="po-btn primary" @click="startNew"><Plus/> New Bill Entry</button><button v-else class="po-btn" @click="back"><ArrowLeft/> Back to list</button><span v-if="view==='detail'" class="po-pill" :class="slug(form.status)">{{ form.status }}</span></div></header>
<div v-if="error" class="po-alert error">{{ error }}</div><div v-if="notice" class="po-alert success">{{ notice }}</div>
<template v-if="view==='list'"><section class="po-metrics"><article v-for="card in metrics" :key="card.label" :class="card.tone"><component :is="card.icon" :size="30"/><div><h2>{{ card.label }}</h2><strong>{{ card.rows.length }} <small>Payments</small></strong><b>{{ money(card.rows.reduce((s,x)=>s+Number(x.amount),0)) }} CAD</b></div></article></section><form class="po-filters"><label>Date Range<span class="po-date-range"><input v-model="filters.from" type="date"><input v-model="filters.to" type="date"></span></label><label>Vendor<select v-model="filters.seller"><option value="">All Vendors</option><option v-for="x in sellers" :key="x.id" :value="x.id">{{ x.seller_name }}</option></select></label><label>Status<select v-model="filters.status"><option value="">All Status</option><option>Draft</option><option>Posted</option></select></label><button class="po-btn" type="button" @click="filters=initialFilters()"><RotateCcw/> Reset</button></form><section class="po-list"><header class="po-section-head"><h2>Bill Payment List</h2><div class="po-actions"><button class="po-btn primary" @click="startNew"><Plus/> New Bill Entry</button><button class="po-btn green" @click="exportExcel"><Download/> Export</button></div></header><div class="po-table-scroll"><table class="po-list-table"><thead><tr><th>No.</th><th>Payment No.</th><th>Date</th><th>Vendor</th><th>Method</th><th>Bank Account</th><th>Reference</th><th>Amount</th><th>Write Off</th><th>Status</th><th>Created By</th><th>View</th></tr></thead><tbody><tr v-for="(row,index) in filtered" :key="row.id"><td>{{ index+1 }}</td><td><button class="po-link" @click="openPayment(row)">{{ row.payment_no }}</button></td><td>{{ dateLabel(row.payment_date) }}</td><td>{{ row.seller?.seller_name }}</td><td>{{ row.payment_method }}</td><td>{{ row.bank_account||'-' }}</td><td>{{ row.reference_no||'-' }}</td><td class="po-number">{{ money(row.amount) }} {{ row.currency_code }}</td><td>{{ money(row.write_off) }}</td><td><span class="po-pill" :class="slug(row.status)">{{ row.status }}</span></td><td>{{ row.creator?.name||'-' }}</td><td><button class="po-btn compact" @click="openPayment(row)"><Eye/> View</button></td></tr><tr v-if="!filtered.length"><td colspan="12" class="po-empty">No bill payments found.</td></tr></tbody></table></div><div class="po-action-bar"><button class="po-btn" @click="printPage"><Printer/> Print</button><button class="po-btn green" @click="exportExcel"><FileSpreadsheet/> Export Excel</button></div></section></template>
<div v-else class="po-workspace"><section class="po-document"><header class="po-document-head"><div class="po-heading"><ReceiptText/><h2>Bill Payment</h2></div><div class="po-actions"><b>{{ form.payment_no||'New payment' }}</b><span class="po-pill" :class="slug(form.status)">{{ form.status }}</span><button class="po-icon" @click="printPage"><Printer/></button><button class="po-icon" @click="emailPayment"><Mail/></button></div></header><div class="po-document-body">
<div class="po-details-grid"><section><h3>1. Select Seller (Vendor)</h3><div v-if="editing" class="po-field"><label>Vendor</label><i>:</i><select v-model="form.seller_id" @change="selectSeller"><option :value="null" disabled>Select vendor</option><option v-for="x in sellers" :key="x.id" :value="x.id">{{ x.seller_name }}</option></select></div><Field label="Vendor ID" :model-value="vendorId"/><Field label="Vendor Name" :model-value="vendor.seller_name"/><Field label="Contact Person" :model-value="vendor.contact_person"/><Field label="Phone" :model-value="vendor.phone"/><Field label="Email" :model-value="vendor.email"/><Field label="Address" :model-value="vendor.address" multiline/><Field label="Tax Number" :model-value="vendor.tax_number"/><Field label="Current Balance" :model-value="money(vendorBalance)+' '+form.currency_code"/></section><section><h3>Payment Information</h3><Field label="Payment Date" v-model="form.payment_date" :editable="editing" type="date" :display-value="dateLabel(form.payment_date)"/><Field label="Payment Number" v-model="form.payment_no" :editable="editing"/><Field label="Payment Method" v-model="form.payment_method" :editable="editing" :options="methods"/><Field label="Payment Status" :model-value="form.status"/><Field label="Bank Account" v-model="form.bank_account" :editable="editing"/><Field label="Reference No." v-model="form.reference_no" :editable="editing"/><Field label="Currency" v-model="form.currency_code" :editable="editing" :options="currencies"/><Field label="Notes" v-model="form.notes" :editable="editing" multiline/></section><section><h3>Additional Options</h3><label class="po-field"><span>Take Discount</span><input v-model="form.take_discount" type="checkbox" :disabled="!editing"></label><label class="po-field"><span>Group by Invoice</span><input v-model="form.group_by_invoice" type="checkbox" :disabled="!editing"></label><Field label="Discount Date" v-model="form.discount_date" :editable="editing" type="date"/><Field label="Write Off" v-model="form.write_off" :editable="editing" type="number"/><Field label="Write Off Account" v-model="form.write_off_account" :editable="editing"/><Field label="Memo" v-model="form.memo" :editable="editing" multiline/></section></div>
<section class="po-items"><div class="po-section-head"><h3>2. Unpaid Invoices</h3><b>Total selected: {{ money(allocationTotal) }} {{ form.currency_code }}</b></div><div class="po-table-scroll"><table><thead><tr><th>Select</th><th>Invoice No.</th><th>Invoice Date</th><th>Due Date</th><th>Original Amount</th><th>Paid Amount</th><th>Balance Due</th><th>Payment Amount</th><th>Payment Status</th><th>Days Overdue</th></tr></thead><tbody><tr v-for="x in eligibleInvoices" :key="x.id"><td><input type="checkbox" :checked="isAllocated(x.id)" :disabled="!editing" @change="toggleInvoice(x,$event.target.checked)"></td><td>{{ x.invoice_no }}</td><td>{{ dateLabel(x.invoice_date) }}</td><td>{{ dateLabel(x.due_date) }}</td><td>{{ money(x.total) }}</td><td>{{ money(x.paid) }}</td><td>{{ money(invoiceDue(x)) }}</td><td><input v-if="editing&&isAllocated(x.id)" :value="allocation(x.id).amount" type="number" min="0" :max="invoiceDue(x)" step=".01" @input="setAllocation(x.id,$event.target.value)"><span v-else>{{ money(allocation(x.id)?.amount||0) }}</span></td><td>{{ x.payment_status }}</td><td>{{ overdueDays(x) }}</td></tr><tr v-if="!eligibleInvoices.length"><td colspan="10" class="po-empty">Select a vendor with approved unpaid invoices.</td></tr></tbody></table></div></section>
<section class="po-items"><div class="po-section-head"><h3>3. Related Documents</h3></div><div class="po-table-scroll"><table><thead><tr><th>Doc Type</th><th>Doc No.</th><th>Doc Date</th><th>Original Amount</th><th>Status</th></tr></thead><tbody><tr v-for="x in relatedRows" :key="x.type+x.id"><td>{{ x.type }}</td><td>{{ x.number }}</td><td>{{ dateLabel(x.date) }}</td><td :class="{'po-negative':x.negative}">{{ x.negative?'('+money(x.total)+')':money(x.total) }}</td><td>{{ x.status }}</td></tr><tr v-if="!relatedRows.length"><td colspan="5" class="po-empty">Related returns and notes appear after the draft is saved.</td></tr></tbody></table></div></section>
<section class="po-items"><div class="po-section-head"><h3>4. Payment Allocation</h3></div><div class="po-table-scroll"><table><thead><tr><th>Apply To</th><th>Document Type</th><th>Document No.</th><th>Due Date</th><th>Balance Due</th><th>Payment Amount</th><th>Method</th></tr></thead><tbody><tr v-for="a in form.allocations" :key="a.purchase_invoice_id"><td><Check/></td><td>Invoice</td><td>{{ invoiceById(a.purchase_invoice_id)?.invoice_no }}</td><td>{{ dateLabel(invoiceById(a.purchase_invoice_id)?.due_date) }}</td><td>{{ money(invoiceDue(invoiceById(a.purchase_invoice_id))) }}</td><td>{{ money(a.amount) }}</td><td>{{ form.payment_method }}</td></tr></tbody><tfoot><tr><th colspan="5">Amount to be Paid</th><th>{{ money(allocationTotal) }}</th><th>{{ form.currency_code }}</th></tr><tr><th colspan="5">Write Off Amount</th><th>{{ money(form.write_off) }}</th><th>{{ form.currency_code }}</th></tr><tr><th colspan="5">Remaining Unallocated</th><th :class="{'po-negative':remaining!==0}">{{ money(remaining) }}</th><th>{{ form.currency_code }}</th></tr></tfoot></table></div></section>
<section v-if="form.attachments.length" class="po-attachments"><h3>Attachments</h3><button v-for="x in form.attachments" :key="x.id" class="po-btn compact" @click="downloadAttachment(x)"><Paperclip/> {{ x.name }}</button></section></div>
<footer class="po-document-footer"><div class="po-actions"><button class="po-btn" @click="startNew"><Plus/> New</button><button class="po-btn" :disabled="editing||form.status!=='Draft'" @click="editing=true"><Pencil/> Edit</button><button class="po-btn danger" :disabled="!form.id||form.status!=='Draft'" @click="deletePayment"><Trash2/> Delete</button><button class="po-btn primary" :disabled="!editing||remaining!==0" @click="savePayment"><Save/> Save</button><button v-if="editing" class="po-btn" @click="cancel"><X/> Cancel</button><button class="po-btn" @click="printPage"><Printer/> Print</button><button class="po-btn" @click="savePdf"><FileDown/> Save PDF</button><button class="po-btn" @click="emailPayment"><Mail/> Email</button><button class="po-btn" :disabled="!form.id" @click="fileInput.click()"><Paperclip/> Attach File</button><input ref="fileInput" class="po-hidden" type="file" @change="upload"><button class="po-btn" :disabled="!form.id" @click="modal='audit'"><History/> Audit Log</button><button class="po-btn green" :disabled="!canPost" @click="postPayment"><FileCheck/> Post Payment</button></div></footer></section>
<aside class="po-sidebar"><section><h3>Transaction Tracker</h3><div class="po-table-scroll"><table class="po-tracker"><thead><tr><th>Doc. Type</th><th>No.</th><th>Date</th><th>Balance</th><th>Status</th></tr></thead><tbody><template v-for="a in form.allocations" :key="a.id||a.purchase_invoice_id"><tr><td>Purchase Invoice</td><td>{{ a.purchase_invoice?.invoice_no||invoiceById(a.purchase_invoice_id)?.invoice_no }}</td><td>{{ dateLabel(a.purchase_invoice?.invoice_date||invoiceById(a.purchase_invoice_id)?.invoice_date) }}</td><td>{{ money(invoiceDue(a.purchase_invoice||invoiceById(a.purchase_invoice_id))) }}</td><td>{{ a.purchase_invoice?.payment_status||invoiceById(a.purchase_invoice_id)?.payment_status }}</td></tr></template><tr><td>Bill Payment</td><td>{{ form.payment_no||'-' }}</td><td>{{ dateLabel(form.payment_date) }}</td><td>-{{ money(form.amount) }}</td><td>{{ form.status }}</td></tr></tbody><tfoot><tr><th>Net Payable Balance</th><th colspan="4">{{ money(Math.max(0,vendorBalance-Number(form.amount||0)-Number(form.write_off||0))) }} {{ form.currency_code }}</th></tr></tfoot></table></div></section><section><h3>Current Bill Payment Details</h3><Field label="Bill Payment No." :model-value="form.payment_no"/><Field label="Vendor ID" :model-value="vendorId"/><Field label="Vendor Name" :model-value="vendor.seller_name"/><Field label="Payment Date" :model-value="dateLabel(form.payment_date)"/><Field label="Payment Method" :model-value="form.payment_method"/><Field label="Payment Status" :model-value="form.status"/><Field label="Payment Amount" :model-value="money(form.amount)+' '+form.currency_code"/><Field label="Bank Account" :model-value="form.bank_account"/><Field label="Reference No." :model-value="form.reference_no"/><Field label="Notes" :model-value="form.notes" multiline/></section><section><h3>Payment Summary</h3><Field label="Total Unpaid Invoices" :model-value="money(vendorBalance)"/><Field label="Payment Amount" :model-value="money(form.amount)"/><Field label="Write Off Amount" :model-value="money(form.write_off)"/><Field label="Remaining After Payment" :model-value="money(Math.max(0,vendorBalance-Number(form.amount||0)-Number(form.write_off||0)))"/></section></aside></div>
<div v-if="modal" class="po-modal-backdrop" @click.self="modal=''"> <section class="po-modal"><header><h2>Bill Payment Audit Log</h2><button class="po-icon" @click="modal=''"><X/></button></header><table><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody><tr v-for="x in form.activities" :key="x.id"><td>{{ dateTimeLabel(x.created_at) }}</td><td>{{ x.actor }}</td><td>{{ x.action }}</td><td>{{ details(x.changes) }}</td></tr></tbody></table></section></div>
</main></AccountLayout></template>
<script setup>
import{computed,onMounted,ref}from'vue';import{ReceiptText,Search,Plus,ArrowLeft,RotateCcw,Download,Eye,Printer,Mail,FileSpreadsheet,Pencil,Trash2,Save,X,FileDown,Paperclip,History,FileCheck,Check,WalletCards,Clock,BadgeCheck}from'lucide-vue-next';import AccountLayout from'../components/AccountLayout.vue';import Field from'../components/PurchaseOrderField.vue';import client from'../api/client';import{today,money,dateLabel,dateTimeLabel,roundMoney}from'../utils/purchaseOrders'
const rows=ref([]),sellers=ref([]),invoices=ref([]),methods=ref(['Bank Transfer','Cheque','Credit Card']),currencies=ref(['CAD','USD']),view=ref('list'),form=ref({}),editing=ref(false),busy=ref(false),error=ref(''),notice=ref(''),modal=ref(''),fileInput=ref(null);const initialFilters=()=>({search:'',seller:'',status:'',from:'',to:''}),filters=ref(initialFilters()),blank=()=>({id:null,payment_no:'',seller_id:null,payment_date:today(),status:'Draft',payment_method:'Bank Transfer',bank_account:'Operating Account',reference_no:'',currency_code:'CAD',amount:0,write_off:0,write_off_account:'',take_discount:false,group_by_invoice:false,discount_date:'',memo:'',notes:'',allocations:[],related_documents:{returns:[],debit_notes:[],credit_notes:[]},activities:[],attachments:[],seller:null})
const slug=x=>String(x||'').toLowerCase().replace(/\s+/g,'-'),vendor=computed(()=>form.value.seller||sellers.value.find(x=>x.id===Number(form.value.seller_id))||{}),vendorId=computed(()=>vendor.value.id?'VEND-'+String(vendor.value.id).padStart(4,'0'):'-'),eligibleInvoices=computed(()=>invoices.value.filter(x=>Number(x.seller_id)===Number(form.value.seller_id)&&x.status==='Approved'&&x.currency_code===form.value.currency_code&&invoiceDue(x)>0)),vendorBalance=computed(()=>roundMoney(eligibleInvoices.value.reduce((s,x)=>s+invoiceDue(x),0))),allocationTotal=computed(()=>roundMoney((form.value.allocations||[]).reduce((s,x)=>s+Number(x.amount||0),0))),remaining=computed(()=>roundMoney(Number(form.value.amount||0)-allocationTotal.value)),canPost=computed(()=>form.value.id&&form.value.status==='Draft'&&!editing.value&&remaining.value===0),filtered=computed(()=>rows.value.filter(x=>{const f=filters.value,q=f.search.toLowerCase(),d=String(x.payment_date).slice(0,10);return(!q||[x.payment_no,x.reference_no,x.seller?.seller_name].some(v=>String(v||'').toLowerCase().includes(q)))&&(!f.seller||Number(x.seller_id)===Number(f.seller))&&(!f.status||x.status===f.status)&&(!f.from||d>=f.from)&&(!f.to||d<=f.to)})),metrics=computed(()=>[{label:'Total Bill Payments',rows:filtered.value,icon:WalletCards,tone:'blue'},{label:'Draft Payments',rows:filtered.value.filter(x=>x.status==='Draft'),icon:Clock,tone:'amber'},{label:'Posted Payments',rows:filtered.value.filter(x=>x.status==='Posted'),icon:BadgeCheck,tone:'green'}]);const relatedRows=computed(()=>{const d=form.value.related_documents||{};return[...(d.returns||[]).map(x=>({type:'Purchase Return',id:x.id,number:x.return_no,date:x.return_date,total:x.total,status:x.status,negative:true})),...(d.debit_notes||[]).map(x=>({type:'Debit Note',id:x.id,number:x.debit_note_no,date:x.debit_note_date,total:x.total,status:x.status,negative:true})),...(d.credit_notes||[]).map(x=>({type:'Credit Note',id:x.id,number:x.credit_note_no,date:x.credit_note_date,total:x.total,status:x.status,negative:false}))]})
const apiError=e=>Object.values(e.response?.data?.errors||{})[0]?.[0]||e.response?.data?.message||e.message;async function all(url,params={}){let p=1,last=1,out=[];do{const{data}=await client.get(url,{params:{...params,per_page:100,page:p}}),b=data.data;out.push(...(b?.data||b||[]));last=b?.last_page||1;p++}while(p<=last);return out}async function load(){const r=await Promise.allSettled([all('/bill-payments'),all('/sellers',{is_active:1}),all('/purchase-invoices'),all('/payment-methods'),all('/currencies')]),v=i=>r[i].status==='fulfilled'?r[i].value:[];rows.value=v(0);sellers.value=v(1);invoices.value=v(2);if(v(3).length)methods.value=v(3).filter(x=>x.status_active).map(x=>x.name);if(v(4).length)currencies.value=v(4).map(x=>x.currency_code)}function normalize(x){const b=blank();return{...b,...x,seller_id:x.seller_id?Number(x.seller_id):null,payment_date:String(x.payment_date||today()).slice(0,10),discount_date:String(x.discount_date||'').slice(0,10),amount:Number(x.amount||0),write_off:Number(x.write_off||0),allocations:(x.allocations||[]).map(a=>({...a,amount:Number(a.amount)})),related_documents:x.related_documents||b.related_documents,activities:x.activities||[],attachments:x.attachments||[]}}
function invoiceDue(x){return x?roundMoney(Number(x.total||0)-Number(x.paid||0)):0}function overdueDays(x){if(!x?.due_date)return 0;return Math.max(0,Math.floor((new Date(today())-new Date(String(x.due_date).slice(0,10)))/86400000))}function invoiceById(id){return invoices.value.find(x=>x.id===Number(id))}function allocation(id){return form.value.allocations.find(x=>Number(x.purchase_invoice_id)===Number(id))}function isAllocated(id){return!!allocation(id)}function toggleInvoice(x,checked){if(checked)form.value.allocations.push({purchase_invoice_id:x.id,amount:invoiceDue(x)});else form.value.allocations=form.value.allocations.filter(a=>Number(a.purchase_invoice_id)!==Number(x.id));form.value.amount=allocationTotal.value}function setAllocation(id,value){allocation(id).amount=Math.max(0,Number(value)||0);form.value.amount=allocationTotal.value}function selectSeller(){form.value.seller=sellers.value.find(x=>x.id===Number(form.value.seller_id))||null;form.value.allocations=[];form.value.amount=0}
function startNew(){form.value=blank();editing.value=true;view.value='detail'}async function openPayment(x){busy.value=true;try{const{data}=await client.get('/bill-payments/'+x.id);form.value=normalize(data.data);editing.value=false;view.value='detail'}catch(e){error.value=apiError(e)}finally{busy.value=false}}function back(){view.value='list';editing.value=false}async function cancel(){form.value.id?await openPayment(form.value):back()}async function savePayment(){if(!form.value.seller_id||!form.value.allocations.length||remaining.value!==0){error.value='Select a vendor and allocate the full payment amount.';return}try{const{data}=form.value.id?await client.put('/bill-payments/'+form.value.id,form.value):await client.post('/bill-payments',form.value);form.value=normalize(data.data);editing.value=false;await load();notice.value='Bill payment draft saved.'}catch(e){error.value=apiError(e)}}async function postPayment(){if(!confirm('Post this payment? Posted payments cannot be edited or deleted.'))return;try{const{data}=await client.post('/bill-payments/'+form.value.id+'/post');form.value=normalize(data.data);await load();notice.value='Bill payment posted.'}catch(e){error.value=apiError(e)}}async function deletePayment(){if(!confirm('Delete '+form.value.payment_no+'?'))return;try{await client.delete('/bill-payments/'+form.value.id);await load();back()}catch(e){error.value=apiError(e)}}
async function upload(e){const f=e.target.files[0];if(!f)return;const b=new FormData();b.append('file',f);try{const{data}=await client.post('/bill-payments/'+form.value.id+'/attachments',b);form.value=normalize(data.data)}catch(x){error.value=apiError(x)}finally{e.target.value=''}}async function downloadAttachment(f){const{data}=await client.get('/bill-payments/'+form.value.id+'/attachments/'+f.id,{responseType:'blob'});download(data,f.name)}function download(b,n){const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function details(v){try{return Object.entries(typeof v==='string'?JSON.parse(v):v||{}).map(([k,x])=>k+': '+x).join(', ')}catch{return''}}function printPage(){window.print()}function emailPayment(){window.location.href='mailto:'+encodeURIComponent(vendor.value.email||'')+'?subject='+encodeURIComponent('Bill Payment '+(form.value.payment_no||''))+'&body='+encodeURIComponent('Payment amount: '+form.value.currency_code+' '+money(form.value.amount))}async function exportExcel(){const{default:ExcelJS}=await import('exceljs'),b=new ExcelJS.Workbook(),s=b.addWorksheet('Bill Payments');s.addRow(['Payment No','Date','Vendor','Method','Reference','Currency','Amount','Write Off','Status']);filtered.value.forEach(x=>s.addRow([x.payment_no,dateLabel(x.payment_date),x.seller?.seller_name,x.payment_method,x.reference_no,x.currency_code,Number(x.amount),Number(x.write_off),x.status]));s.columns.forEach(x=>x.width=22);download(new Blob([await b.xlsx.writeBuffer()]),'bill-payments.xlsx')}async function savePdf(){const{default:jsPDF}=await import('jspdf'),p=new jsPDF();p.setFontSize(18);p.text('Bill Payment '+(form.value.payment_no||''),15,18);p.setFontSize(10);p.text('Vendor: '+(vendor.value.seller_name||'-'),15,30);p.text('Amount: '+form.value.currency_code+' '+money(form.value.amount),15,38);p.text('Method: '+form.value.payment_method,15,46);p.save((form.value.payment_no||'bill-payment')+'.pdf')}onMounted(async()=>{busy.value=true;try{await load()}catch(e){error.value=apiError(e)}finally{busy.value=false}})
</script><style src="../assets/purchase-orders.css"></style>
